# -*- coding: utf-8 -*-
"""أدوات تجارة إلكترونية مبتكرة (5): دورة تحويل النقد، ربحية مناطق الشحن، مخزون الأمان، تذكير إعادة الشراء، حمل خدمة العملاء."""
from biz_tools import F, S, add, CATS, T

add('cash-conversion-cycle', 'ecom', '🔄', 'دورة تحويل النقد: كم رأس مال يحبسه متجرك في المخزون والتحصيل؟',
    'أغلب المتاجر النامية لا تفلس من الخسارة بل من نقص السيولة. أدخل أيام المخزون وتحصيل الدفع (الدفع عند الاستلام يتأخر أيامًا) وسداد المورد لترى رأس المال المحبوس وكم تحتاج لتنمو، وأي رافعة تحرر أكبر نقد.',
    [F('rev', 'الإيراد الشهري', 'n', 200000), F('cg', 'تكلفة البضاعة من الإيراد %', 'n', 55),
     F('dio', 'أيام بقاء المخزون قبل البيع', 'n', 60), F('dso', 'أيام تحصيل المبيعات (COD/بوابة الدفع)', 'n', 7),
     F('dpo', 'أيام سداد المورد (0 إن كان الدفع مقدمًا)', 'n', 0), F('g', 'نمو مستهدف في الإيراد %', 'n', 50)],
    r'''function compute(v){
const rev=num(v.rev),cg=num(v.cg)/100,dio=num(v.dio),dso=num(v.dso),dpo=num(v.dpo),g=num(v.g)/100;
const dr=rev/30,dc=rev*cg/30,ccc=dio+dso-dpo;
const inv=dc*dio,ar=dr*dso,ap=dc*dpo,wc=inv+ar-ap,need=wc*g;
const lev=[['تقليل المخزون 10 أيام',dc*10],['تسريع التحصيل 3 أيام',dr*3],['إطالة سداد المورد 15 يومًا',dc*15]].sort((a,b)=>b[1]-a[1]);
return kpis([kpi('دورة تحويل النقد',f(ccc,0)+' يوم',ccc>60?'bad':''),kpi('رأس المال المحبوس',f(wc,0)),kpi('محبوس في المخزون',f(inv,0)),kpi('محبوس في التحصيل',f(ar,0)),kpi('تمويل مطلوب للنمو '+f(g*100,0)+'%',f(need,0),need>wc*.3?'bad':'')])
+'<h4>أي رافعة تحرر أكبر نقد؟</h4>'+tbl(['الإجراء','نقد يتحرر'],lev.map(x=>[x[0],f(x[1],0)]))
+rec(['الدورة = أيام المخزون + أيام التحصيل − أيام سداد المورد = '+f(ccc,0)+' يوم: هذا عدد الأيام التي تموّل فيها البضاعة من جيبك.','الرافعة الأقوى لديك: «'+lev[0][0]+'» تحرر '+f(lev[0][1],0)+'.','النمو يستهلك نقدًا قبل أن يدرّه: خطط لتمويل '+f(need,0)+' أو أبطئ النمو.'])}''')

add('shipping-zone-profit-map', 'ecom', '🗺️', 'خريطة ربحية الشحن حسب المنطقة: أين تخسر على كل طلب؟',
    'متوسط الربح قد يُخفي مدنًا تخسر فيها. أدخل لكل منطقة تكلفة الشحن عليك وما يدفعه العميل ونسبة المرتجع لتعرف الربح الفعلي للطلب، وأي منطقة تحتاج رسم شحن أعلى أو حدًا أدنى للطلب.',
    [F('d', 'المناطق (منطقة | طلبات شهريًا | متوسط قيمة الطلب | هامش المنتج % | تكلفة الشحن عليك | يدفعه العميل | مرتجعات %)', 'textarea',
       'الرياض | 400 | 180 | 40 | 18 | 15 | 6\nجدة | 250 | 175 | 40 | 22 | 15 | 7\nالدمام | 150 | 190 | 40 | 24 | 20 | 8\nأبها | 40 | 160 | 40 | 38 | 20 | 12\nتبوك | 25 | 170 | 40 | 45 | 20 | 14', r=6),
     F('t', 'الربح المستهدف للطلب', 'n', 15)],
    r'''function compute(v){
const R=lines(v.d).map(x=>({z:x[0],n:num(x[1]),a:num(x[2]),m:num(x[3])/100,c:num(x[4]),p:num(x[5]),r:num(x[6])/100})).filter(x=>x.n>0);
if(!R.length)return'<b>أدخل منطقة واحدة على الأقل.</b>';
const t=num(v.t);R.forEach(x=>{x.pr=x.a*x.m-x.c+x.p-x.r*x.c;x.tot=x.pr*x.n;x.need=Math.max(0,t-x.a*x.m+x.c*(1+x.r));x.min=x.pr<t&&x.m>0?Math.ceil((t+x.c*(1+x.r)-x.p)/x.m):0});
const tot=R.reduce((s,x)=>s+x.tot,0),ord=R.reduce((s,x)=>s+x.n,0),loss=R.filter(x=>x.pr<0);
return kpis([kpi('ربح الطلب (متوسط)',f(tot/ord,1)),kpi('إجمالي الربح بعد الشحن',f(tot,0)),kpi('مناطق خاسرة',loss.length+' من '+R.length,loss.length?'bad':''),kpi('خسارة المناطق الخاسرة',f(loss.reduce((s,x)=>s+x.tot,0),0),loss.length?'bad':'')])
+tbl(['المنطقة','طلبات','ربح الطلب','ربح المنطقة','رسم الشحن المطلوب للهدف','حد أدنى للطلب'],R.map(x=>[x.z,f(x.n,0),f(x.pr,1),f(x.tot,0),f(x.need,0),x.min?f(x.min,0):'—']))
+rec(['ربح الطلب = قيمة الطلب × الهامش − تكلفة الشحن + ما يدفعه العميل − (نسبة المرتجع × تكلفة شحن إضافية للمرتجع).','«رسم الشحن المطلوب» هو ما يجب أن يدفعه العميل لتبلغ هدف الربح للطلب؛ إن كان صفرًا فالشحن المجاني مقبول هناك.','«حد أدنى للطلب» هو القيمة التي ترفع ربح الطلب لهدفك دون تغيير رسم الشحن.'])}''')

add('stockout-safety-stock', 'ecom', '📦', 'مخزون الأمان ونقطة إعادة الطلب: كم يكلفك نفاد المنتج؟',
    'أدخل متوسط المبيعات اليومية وتذبذبها ومدة التوريد ومستوى الخدمة لتحصل على مخزون الأمان ونقطة إعادة الطلب، ومتى تطلب الآن، وكم تخسر من الربح في كل يوم نفاد.',
    [F('d', 'متوسط المبيعات اليومية (وحدة)', 'n', 12), F('sd', 'الانحراف المعياري اليومي (تذبذب المبيعات)', 'n', 5),
     F('lt', 'مدة التوريد بالأيام', 'n', 20), S('z', 'مستوى الخدمة', [['1.28', '90%'], ['1.65', '95%'], ['2.33', '99%']], '1.65'),
     F('mg', 'ربح الوحدة', 'n', 35), F('st', 'المخزون الحالي', 'n', 300), F('dl', 'تأخير محتمل من المورد بالأيام', 'n', 7)],
    r'''function compute(v){
const d=num(v.d),sd=num(v.sd),L=num(v.lt),z=num(v.z),m=num(v.mg),st=num(v.st),dl=num(v.dl);
const ss=Math.ceil(z*sd*Math.sqrt(L)),rop=Math.ceil(d*L+ss),cover=d?st/d:0,toOrder=st<=rop,days=d?Math.max(0,(st-rop)/d):0;
const lossDay=d*m,delayLoss=Math.max(0,d*(L+dl)-st)*m;
return kpis([kpi('مخزون الأمان',f(ss,0)+' وحدة'),kpi('نقطة إعادة الطلب',f(rop,0)+' وحدة'),kpi('يكفي المخزون',f(cover,0)+' يوم',cover<L?'bad':''),kpi('خسارة ربح كل يوم نفاد',f(lossDay,0)),kpi('خسارة لو تأخر المورد '+f(dl,0)+' يوم',f(delayLoss,0),delayLoss>0?'bad':'')])
+(toOrder?'<div class="note">⚠️ المخزون الحالي عند نقطة إعادة الطلب أو دونها: اطلب الآن.</div>':'<div class="note">✅ لديك '+f(days,0)+' يومًا قبل الوصول لنقطة إعادة الطلب.</div>')
+rec(['مخزون الأمان = Z × الانحراف × √مدة التوريد، ويغطي تذبذب الطلب فقط لا تأخر المورد.','لتغطية تأخر المورد '+f(dl,0)+' أيام أضف '+f(d*dl,0)+' وحدة تقريبًا فوق مخزون الأمان.','فكّر في مورد احتياطي للمنتجات الأعلى ربحًا: خسارة اليوم الواحد '+f(lossDay,0)+'.'])}''')

add('replenishment-reminder-planner', 'ecom', '⏰', 'مخطط تذكير إعادة الشراء للمنتجات المستهلكة',
    'للمنتجات التي تنتهي (عطور، مكملات، عناية، قهوة): حدّد يوم إرسال التذكير قبل نفاد المنتج وقدّر الإيراد من رسائل واتساب أو بريد تُرسل لعملائك السابقين وعائدها مقابل تكلفتها.',
    [F('life', 'مدة استهلاك المنتج بالأيام', 'n', 30), F('cus', 'عملاء اشتروا المنتج آخر 12 شهرًا', 'n', 1200),
     F('cr', 'نسبة التذكير → شراء (تقدير متحفظ %)', 'n', 8), F('aov', 'قيمة طلب إعادة الشراء', 'n', 120),
     F('mg', 'هامش الربح %', 'n', 45), F('msgs', 'عدد الرسائل في السلسلة', 'n', 3), F('mc', 'تكلفة الرسالة الواحدة', 'n', 0.25)],
    r'''function compute(v){
const L=num(v.life),c=num(v.cus),cr=num(v.cr)/100,aov=num(v.aov),m=num(v.mg)/100,n=Math.max(1,num(v.msgs)),mc=num(v.mc);
const buyers=c*cr,rev=buyers*aov,profit=rev*m,cost=c*n*mc,net=profit-cost;
const sched=[[Math.max(1,L-7),'تذكير مبكر: «قارب منتجك على الانتهاء»'],[L,'يوم النفاد المتوقع + عرض بسيط'],[L+14,'استرجاع: خصم لمن لم يشترِ']].slice(0,Math.max(1,Math.min(3,n)));
return kpis([kpi('مشترون متوقعون',f(buyers,0)),kpi('إيراد إضافي',f(rev,0)),kpi('تكلفة الرسائل',f(cost,0)),kpi('صافي الربح',f(net,0),net<0?'bad':''),kpi('العائد على كل ريال رسائل',cost?f(profit/cost,1)+'x':'—')])
+'<h4>جدول الإرسال بعد تاريخ الشراء</h4>'+tbl(['اليوم','المحتوى'],sched.map(s=>[f(s[0],0),s[1]]))
+rec(['أرسل أول تذكير قبل النفاد بأسبوع حتى يصل الطلب قبل انتهاء المنتج.','قسّم العملاء: من اشترى مرتين يحتاج رسالة أخف ممن اشترى مرة.','نسبة التحويل رقم تقديري؛ قِسها على 100 عميل أولًا قبل التعميم.'])}''')

add('support-load-planner', 'ecom', '🎧', 'مخطط حمل خدمة العملاء: كم موظفًا يحتاج متجرك؟',
    'من عدد الطلبات ونسبة تواصل العملاء ومدة المعالجة يحسب عدد الموظفين اللازم في الأيام العادية والذروة، وتكلفة الدعم لكل طلب، وكم توفّر صفحة تتبع الشحن والأسئلة الشائعة.',
    [F('o', 'طلبات شهريًا', 'n', 3000), F('cr', 'نسبة الطلبات التي يتواصل أصحابها %', 'n', 25), F('aht', 'متوسط وقت المعالجة بالدقائق', 'n', 6),
     F('hrs', 'ساعات العمل الفعلية للموظف يوميًا', 'n', 6), F('days', 'أيام العمل شهريًا', 'n', 26), F('occ', 'نسبة الإشغال المقبولة %', 'n', 75),
     F('pk', 'مضاعف أسابيع الذروة', 'n', 2), F('sal', 'تكلفة الموظف شهريًا', 'n', 5000), F('dfl', 'نسبة التواصل التي يمكن حذفها بصفحة تتبع/أسئلة شائعة %', 'n', 30)],
    r'''function compute(v){
const o=num(v.o),cr=num(v.cr)/100,aht=num(v.aht),h=num(v.hrs),d=num(v.days),oc=num(v.occ)/100,pk=num(v.pk),sal=num(v.sal),df=num(v.dfl)/100;
const cap=h*d*oc,hoursNeed=o*cr*aht/60,ag=cap?hoursNeed/cap:0,agPk=ag*pk,cost=ag>0?Math.ceil(ag)*sal:0;
const saved=ag*df,after=Math.ceil(ag*(1-df))*sal;
return kpis([kpi('تذاكر شهريًا',f(o*cr,0)),kpi('موظفون (عادي)',f(ag,1)),kpi('موظفون (ذروة)',f(agPk,1)),kpi('تكلفة الدعم للطلب',f(o?cost/o:0,2)),kpi('وفر بصفحة تتبع وأسئلة شائعة',f(Math.max(0,cost-after),0)+' / شهر')])
+tbl(['الحالة','موظفون','تكلفة شهرية'],[['اليوم',f(Math.ceil(ag),0),f(cost,0)],['موسم الذروة',f(Math.ceil(agPk),0),f(Math.ceil(agPk)*sal,0)],['بعد خفض التواصل '+f(df*100,0)+'%',f(Math.ceil(ag*(1-df)),0),f(after,0)]])
+rec(['الإشغال المقبول '+f(oc*100,0)+'% يترك وقتًا للتذاكر المعقدة والاستراحات؛ لا تخطط لإشغال 100%.','أكثر أسباب التواصل في المتاجر: «أين طلبي؟» — صفحة تتبع برسائل واتساب تلقائية تحذف جزءًا كبيرًا منه.','في الذروة استعن بدوام جزئي أو ردود جاهزة بدل توظيف دائم.'])}''')
